function packForm(formSel, data = {})
{
  $(formSel).serializeArray().map(function(x){
    data[x.name] = x.value;
  });

  return data;
}

function populateForm(formSelector, data) {
  $.each(data, function(key, value){
    $('[name='+key+']', formSelector).val(value);
  });
}

function brDatetoUsa(datestring)
{
  var dateSplitted = datestring.split('/');
  return dateSplitted[2] + '-' + dateSplitted[1] + '-' + dateSplitted[0];
}

function usaDatetoBr(datestring)
{
  var dateSplitted = datestring.split('-');
  return dateSplitted[2] + '/' + dateSplitted[1] + '/' + dateSplitted[0];
}
// Retornando a data padrao EUA com dois digitos no ano
function converterToTwoDigit(dateComplet) {
    if (!dateComplet) return '';
    
    let parts = dateComplet.split('/');
    if (parts.length === 3) {
        return parts[0] + '/' + parts[1] + '/' + parts[2].slice(-2);
    }
    return dateComplet;
}


function dataAtualFormatada(dt){
  var data = new Date(dt),
      dia  = data.getDate().toString(),
      diaF = (dia.length == 1) ? '0'+dia : dia,
      mes  = (data.getMonth()+1).toString(), //+1 pois no getMonth Janeiro começa com zero.
      mesF = (mes.length == 1) ? '0'+mes : mes,
      anoF = data.getFullYear();
  return diaF+"/"+mesF+"/"+anoF;
}

function formattedCurrentDate() {
  const now = new Date();
  return now.getDate().toString().padStart(2, '0')
    + (now.getMonth() + 1).toString().padStart(2, '0')
    + now.getFullYear().toString();
}

function reloadTable(tableId) {
  $("#" + tableId).DataTable().ajax.reload();
}

function convertBrCoinToFloat(valor){

  if(valor === ""){
    valor =  0;
  }else{
    valor = valor.replace(".","");
    valor = valor.replace(",",".");
    valor = parseFloat(valor);
  }
  return valor;

}

function formatFloatToBrCoin(value) {
  let formatter = new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  });

  return formatter.format(value).replace('R$', '').trim();
}

//formatar valor real brasileiro
//funcao similar ao formatFloatToBrCoin
function convertToReal(number, options = {}) {
  const { moneySign = true } = options;

  if(Number.isNaN(number) || !number) return "need a number as the first parameter";

  if(typeof number === "string") { // n1
      number = Number(number);
  }

  let res;

  const config = moneySign ? {style: 'currency', currency: 'BRL'} : {minimumFractionDigits: 2};

  moneySign
  ? res = number.toLocaleString('pt-BR', config)
  : res = number.toLocaleString('pt-BR', config)

  const needComma = number => number <= 1000;
  if(needComma(number)) {
      res = res.toString().replace(".", ",");
  }

  return res; // n2
}

class Crud {
    constructor(resourceName, singularName, pluralName, dataTableColumns) {
        this.singularName = singularName;
        this.resourceModel = new ResourceModel(resourceName);
        this.formSel = '#form-' + resourceName;
        this.$resourceModal = $('#modal-' + resourceName);
        this.$createBtn = $('#create-' + resourceName + '-btn');
        this.$submitBtn = $('#form-save-' + resourceName + '-btn');
        this.$resourceId = $('#' + resourceName + '-id');
        this.$form = $(this.formSel);
        this.$advancedSearchForm = $('#advanced-search-' + resourceName);
        this.resourceTable = new SearaTable(
            'table-' + resourceName,
            resourceName + '/dataTable',
            dataTableColumns,
            singularName,
            pluralName,
            () => packForm('#advanced-search-' + resourceName)
        );
    }

    initialize() {
        this.resourceTable.loadTable();
        this.$createBtn.on('click', () => {
            this._showForm();
        });

        this.$submitBtn.on('click', () => {
            let id = this.$resourceId.val();

            if (!this.$form.parsley().validate()) {
                return;
            }

            if ('' === id) {
                this._storeResource();
                return;
            }

            this._updateAccount(id);
        });

        const thisCrud = this;
        this.$resourceModal.on('shown.bs.modal', function () {
            thisCrud.$form.find('input:first:visible').focus();
        });

        this.$advancedSearchForm.on('change', () => {
            thisCrud.resourceTable.reloadTable();
        });
    }

    editResource(id) {
        SearaLoader.showModal("Carregando dados...");
        const thisCrud = this;
        this.resourceModel.read(id, function (data) {
            thisCrud._showForm();
            populateForm(thisCrud.formSel, data);
            reloadAllMasks();
            thisCrud.$resourceId.val(id);
        }).fail(function (jqXHR) {
            notify.response(jqXHR.responseJSON);
        }).always(function () {
            SearaLoader.hideModal();
        });
    }

    destroyResource(id, confirmationText) {
        const thisCrud = this;
        swal({
            title: 'Atenção',
            text: confirmationText,
            type: 'warning',
            showCancelButton: true
        }).then(function() {
            SearaLoader.showModal('Aguarde ...');
            thisCrud.resourceModel.delete(id, function (response) {
                notify.response(response);
                thisCrud.resourceTable.reloadTable();
            }).fail(function (jqXHR) {
                notify.response(jqXHR.responseJSON);
            }).always(function(){
                SearaLoader.hideModal();
            });
        });
    }

    _showForm() {
        this.$resourceId.val('');
        this.$form.trigger('reset');
        this.$form.parsley().reset();
        this.$resourceModal.modal('show');
    }

    _closeForm() {
        this.$resourceModal.modal('hide');
    }

    _storeResource() {
        let formData = packForm(this.formSel);
        SearaLoader.showModal('Cadastrando ' + this.singularName + ' ...');

        const thisCrud = this;
        this.resourceModel.create(formData, function (response) {
            notify.response(response);
            thisCrud._closeForm();
            thisCrud.resourceTable.reloadTable();
        }).fail(function (jqXHR) {
            notify.response(jqXHR.responseJSON);
        }).always(function () {
            SearaLoader.hideModal();
        });
    }

    _updateAccount(id) {
        let formData = packForm(this.formSel);
        SearaLoader.showModal('Atualizando ' + this.singularName + ' ...');

        const thisCrud = this;
        this.resourceModel.update(id, formData, function (response) {
            notify.response(response);
            thisCrud._closeForm();
            thisCrud.resourceTable.reloadTable();
        }).fail(function (jqXHR) {
            notify.response(jqXHR.responseJSON);
        }).always(function () {
            SearaLoader.hideModal();
        });
    }
}

let ReceivableModule = (function () {
    const columns = [
        {data: 'due_date', name: 'due_date'},
        {data: 'payment_date', name: 'payment_date', className: 'nowrap'},
        {data: 'description', name: 'description'},
        {data: 'category', name: 'category'},
        {data: 'account', name: 'account'},
        {data: 'amount', name: 'amount', className: 'formatted_number'},
        {data: 'paid_amount', name: 'paid_amount', className: 'formatted_number'},
        {data: 'manager', name: 'manager'},
        {data: 'customer', name: 'customer'},
        {data: 'action', name: 'action', orderable: false, searchable: false, className: 'action'},
    ];

    const crud = new Crud(
        'receivable',
        'conta a receber',
        'contas a receber',
        columns
    );

    function updateDebtReliefAmount() {
        let amount = convertBrCoinToFloat($('#pay-receivable-amount').val());
        let lateFeeAmount = convertBrCoinToFloat(
            $('#pay-receivable-late-fee-amount').val()
        );

        let debtReliefAmount = amount - lateFeeAmount;

        populatePayReceivableForm({
            debt_relief_amount: formatFloatToBrCoin(debtReliefAmount)
        });
    }

    function index() {
        crud.initialize();
        $('#modal-receivable').on('hidden.bs.modal', function () {
            $('#repeat_for').closest('div').show();
        });

    }

    function registerAmountEvents(remainingAmount) {
        $('#pay-receivable-amount').off('change');
        $('#pay-receivable-late-fee-amount').off('change');

        $('#pay-receivable-amount').on('change', () => {
            let totalAmount = convertBrCoinToFloat(
                $('#pay-receivable-amount').val()
            );

            let differenceToTheRemainingAmount = totalAmount - remainingAmount;
            if (differenceToTheRemainingAmount > 0) {
                populatePayReceivableForm({
                    late_fee_amount: formatFloatToBrCoin(differenceToTheRemainingAmount)
                });
            }

            updateDebtReliefAmount();
        });
        $("#pay-receivable-late-fee-amount").on('change', updateDebtReliefAmount);
    }

    function deleteReceivable(id) {
        crud.destroyResource(id, 'Essa conta a receber será removida e não pode ser desfeito, deseja continuar?');
    }

    function editReceivable(id) {
        $('#repeat_for').closest('div').hide();
        crud.editResource(id);
    }

    function payReceivable(id) {
        $('#modal-pay-receivable').modal('show');
        let remainingAmount = $('#receivable-' + id).data('remainingAmount');
        let data = {
            // payment_date: formattedCurrentDate(),
            amount: remainingAmount,
            debt_relief_amount: remainingAmount,
            late_fee_amount: "0,00"
        };
        if ($('#payment_date').val().trim() === '') {
            data.payment_date = formattedCurrentDate();
        }
        populateForm('#form-pay-receivable', data);
        reloadAllMasks();
        registerAmountEvents(convertBrCoinToFloat(remainingAmount));

        $('#form-pay-receivable').off('submit');
        $('#form-pay-receivable').on('submit', function () {
            if (!$('#form-pay-receivable').parsley().validate()) {
                return;
            }

            SearaLoader.showModal('Efetivando conta...');
            let data = packForm('#form-pay-receivable');
            data.remaining_amount = remainingAmount;

            SearaAjax.put('/receivable/payment/' + id, data)
                .then(function (response) {
                    notify.response(response);
                    $('#modal-pay-receivable').modal('hide');
                    reloadTable('table-receivable');
                })
                .fail(function (jqXHR) {
                    notify.response(jqXHR.responseJSON);
                })
                .always(function () {
                    SearaLoader.hideModal();
                })
        });
    }

    function populatePayReceivableForm(data) {
        populateForm('#form-pay-receivable', data);
    }

    function generateReceipt(id) {
        swal({
            title: 'Geração de Recibo',
            text: 'Um novo recibo com as informações dessa conta será gerado, deseja continuar?',
            type: 'warning',
            showCancelButton: true
        }).then(function() {
            SearaLoader.showModal('Gerando Recibo ...');
            SearaAjax.put('/receivable/' + id + '/receipt', {}, function (response) {
                notify.response(response);
                window.open(response.location,'_blank');
            }).fail(function (jqXHR) {
                notify.response(jqXHR.responseJSON);
            }).always(function(){
                SearaLoader.hideModal();
            });
        });
    }

    return {
        index,
        deleteReceivable,
        editReceivable,
        payReceivable,
        generateReceipt
    };
})();

$(() => {
    ReceivableModule.index();
    $('#due_date').mask('00/00/0000', {placeholder: "__/__/____"});
    $('#payment_date').mask('00/00/0000', {placeholder: "__/__/____"});
    console.log('financing.receivable');
});
function deleteReceivable(id) {
    ReceivableModule.deleteReceivable(id);
}

function editReceivable(id) {
    ReceivableModule.editReceivable(id);
}

function payReceivable(id) {
    ReceivableModule.payReceivable(id);
}

function generateReceipt(id) {
    ReceivableModule.generateReceipt(id);
}

